307	     * @throws InvalidOwnerFieldsException if one or more required fields are blank
308	     */
309	    private void rejectBlankOwnerFields(OwnerFieldsDto ownerFieldsDto) {
310	        List<String> blankFields = new ArrayList<>();
311	        addIfBlank(blankFields, "firstName", ownerFieldsDto.getFirstName());
312	        addIfBlank(blankFields, "lastName", ownerFieldsDto.getLastName());
313	        addIfBlank(blankFields, "address", ownerFieldsDto.getAddress());
314	        addIfBlank(blankFields, "city", ownerFieldsDto.getCity());
315	        addIfBlank(blankFields, "telephone", ownerFieldsDto.getTelephone());
316	        if (!blankFields.isEmpty()) {
317	            throw new InvalidOwnerFieldsException(blankFields);
