346	    /**
347	     * Validates the owner's optional {@code postcode} against its {@code city} region. Postcode is
348	     * validated only when present, so an owner created without one is accepted unchanged. A supplied
349	     * postcode is already constrained to four digits by Bean Validation on {@link OwnerFieldsDto}; this
350	     * additionally rejects a well-formed postcode that is out of range for the city's region using the
351	     * shared {@link Region#acceptsPostcode(int) region-to-postcode} table ({@code NSW 2000-2099},
352	     * {@code VIC 3000-3099}, {@code QLD 4000-4099}). A city with no known region accepts any 4-digit
353	     * postcode. An out-of-range postcode is reported through an {@link InvalidOwnerPostcodeException},
354	     * which the {@code ExceptionControllerAdvice} renders as a 400 response.
355	     *
356	     * @param city the city of the owner being created
357	     * @param postcode the supplied postcode, or {@code null} when omitted
358	     * @throws InvalidOwnerPostcodeException if the postcode is out of range for the city's region
359	     */
360	    private void rejectInvalidPostcode(String city, String postcode) {
361	        if (postcode == null || postcode.isBlank()) {
362	            return;
363	        }
364	        Region.forCity(city).ifPresent(region -> {
365	            if (!region.acceptsPostcode(Integer.parseInt(postcode))) {
366	                throw new InvalidOwnerPostcodeException(postcode, city);
367	            }
368	        });
369	    }
