377	    /**
378	     * Builds the {@code customerCode} assigned to a newly created owner, formatted
379	     * {@code '<REGION>-<HASH8>'}: {@code REGION} is the owner's canonical region code resolved from
380	     * its {@code postcode} (falling back to its {@code city}) through the shared
381	     * {@link Region#code(String, String)}, and {@code HASH8} is the first 8 upper-case hex characters
382	     * of the SHA-256 digest of the owner's normalized telephone followed by its last name
383	     * (e.g. {@code 'NSW-1A2B3C4D'}). The code carries no sequence number, so it is a deterministic
384	     * function of the owner's region and telephone-plus-name identity.
385	     *
386	     * @param owner the owner being created, with its telephone already normalized
387	     * @return the formatted customer code
388	     */
389	    private String customerCode(Owner owner) {
390	        String region = Region.code(owner.getPostcode(), owner.getCity());
391	        String hash8 = hashPrefix(owner.getTelephone() + owner.getLastName(), CUSTOMER_CODE_HASH_LENGTH);
392	        return region + "-" + hash8;
393	    }
