403	     * @param lastName the last name of the owner being created
404	     * @return the number of existing owners with the same first and last name (case-insensitive)
405	     */
406	    private int namesakeCount(String firstName, String lastName) {
407	        return (int) countOwners(owner -> equalsIgnoreCase(owner.getFirstName(), firstName)
408	            && equalsIgnoreCase(owner.getLastName(), lastName));
